{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 11,
      "text_ar": "ورأيت كيف أن كل الأشياء تحت السماء خضعت لها، ولم يتكلم أحد ضدها - كلا، ولا مخلوق واحد على الأرض.",
      "verse": 6
    },
    {
      "chapter": 11,
      "text_ar": "ورأيت، وإذا النسر قد نهض على مخالبه، ووجه صوته إلى أجنحته قائلاً:",
      "verse": 7
    },
    {
      "chapter": 11,
      "text_ar": "لا تسهروا كلكم في وقت واحد. ليدر كل واحد في مكانه الخاص وليحرس بالتناوب؛",
      "verse": 8
    },
    {
      "chapter": 11,
      "text_ar": "ولكن لتُحفظ الرؤوس للنهاية.",
      "verse": 9
    },
    {
      "chapter": 11,
      "text_ar": "ورأيت، وإذا الصوت لم يخرج من رؤوسها، بل من وسط جسدها.",
      "verse": 10
    }
  ]
}
